files.style.css:
body { margin: 0; min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #0d0e10; color: #f7f5ec; font-family: system-ui, sans-serif; gap: 14px; }
h1 { margin: 0; font-size: 1.4rem; }
p { margin: 0; color: #9a9a94; font-size: 1.2rem; }
#clicker { font-size: 1.6rem; padding: 26px 46px; border-radius: 14px; border: none; background: #b8f23a; color: #101010; cursor: pointer; box-shadow: 0 4px 0 #7fa328; }
#clicker:active { transform: translateY(3px); box-shadow: 0 1px 0 #7fa328; }
#shop { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; }
#shop button { padding: 10px 16px; border-radius: 8px; border: 1px solid #262a33; background: #14161b; color: #f7f5ec; cursor: pointer; }
#shop button:disabled { opacity: 0.45; cursor: not-allowed; }

files.game.js:
let coins = 0, perClick = 1, auto = 0;
const priceClick = { value: 10 };
const priceAuto = { value: 50 };
const scoreEl = document.getElementById('coins');
const upClick = document.getElementById('upClick');
const upAuto = document.getElementById('upAuto');
const clicker = document.getElementById('clicker');

function render() {
  scoreEl.textContent = 'Coins: ' + coins;
  upClick.textContent = 'Sharper finger (+1 per click) — ' + priceClick.value;
  upAuto.textContent = 'Tiny helper (+1 per second) — ' + priceAuto.value;
  upClick.disabled = coins < priceClick.value;
  upAuto.disabled = coins < priceAuto.value;
}

clicker.onclick = () => { coins += perClick; render(); };
upClick.onclick = () => {
  if (coins < priceClick.value) return;
  coins -= priceClick.value; perClick++; priceClick.value += 10; render();
};
upAuto.onclick = () => {
  if (coins < priceAuto.value) return;
  coins -= priceAuto.value; auto++; priceAuto.value += 50; render();
};

setInterval(() => { coins += auto; render(); }, 1000);
render();
